<?php require '../includes/functions.php'; $u=require_role('citizen'); $pdo=db(); $q=$pdo->prepare("SELECT COUNT(*) total,SUM(status IN ('Submitted','Under Review','Assigned','Reopened')) pending,SUM(status='In Progress') progress,SUM(status IN ('Resolved','Closed')) resolved FROM grievances WHERE citizen_id=?"); $q->execute([$u['id']]); $stats=$q->fetch(); $q=$pdo->prepare('SELECT tracking_number,title,status,created_at,id FROM grievances WHERE citizen_id=? ORDER BY created_at DESC LIMIT 8');$q->execute([$u['id']]);$rows=$q->fetchAll();$pageTitle='Citizen dashboard';require '../includes/header.php'; ?>
<h1>Welcome, <?= e($u['full_name']) ?></h1><div class="grid"><?php foreach(['Submitted'=>'total','Pending'=>'pending','In progress'=>'progress','Resolved'=>'resolved'] as $label=>$key): ?><div class="card"><span><?= e($label) ?></span><strong><?= (int)($stats[$key]??0) ?></strong></div><?php endforeach ?></div><div class="actions"><a class="button" href="<?= e(url('citizen/submit.php')) ?>">Submit grievance</a><a class="button" href="<?= e(url('citizen/grievances.php')) ?>">My grievances</a><a class="button" href="<?=e(url('citizen/profile.php'))?>">Profile settings</a></div><section class="panel"><h2>Recent activity</h2><?php if(!$rows): ?><p>No grievances submitted yet.</p><?php else: ?><table><tr><th>Tracking number</th><th>Title</th><th>Status</th><th>Submitted</th><th></th></tr><?php foreach($rows as $g): ?><tr><td><?= e($g['tracking_number']) ?></td><td><?= e($g['title']) ?></td><td class="status status-<?= e($g['status']) ?>"><?= e($g['status']) ?></td><td><?= e($g['created_at']) ?></td><td><a href="<?= e(url('citizen/view.php?id='.$g['id'])) ?>">Details</a></td></tr><?php endforeach ?></table><?php endif ?></section><?php require '../includes/footer.php'; ?>
